/**
 * Every action group bound to a client.
 *
 * @stability stable
 */
export type EnsActions = ApprovalActions &
  DnsActions &
  EventActions &
  MigrationActions &
  NameActions &
  PermissionActions &
  PlanActions &
  PrimaryNameActions &
  RecordActions &
  RegistrationActions &
  RegistryActions &
  ResolverActions &
  RoleActions &
  SubnameActions &
  WrapperActions &
  BatchActions;

/**
 * Adds every ENS action group to a client. Rarely used groups (approval, dns, event, migration,
 * permission, registry, role, wrapper) and `batch` load with their first call, so a client with
 * every action stays small; their own decorators (`migrationActions()`) load with the client.
 *
 * **Example** (A client with every action)
 *
 * ```ts
 * import { Ensforge, ensActions } from "@ensforge/sdk"
 * import { mainnet } from "viem/chains"
 *
 * const ens = Ensforge.create({ chain: mainnet, wallet: walletClient }).extend(ensActions())
 * ```
 *
 * @stability stable
 * @category decorators
 * @since 1.0.0
 */
export const ensActions =
  () =>
  (client: Client<object>): EnsActions => ({
    ...approvalOnDemand(client),
    ...dnsOnDemand(client),
    ...eventOnDemand(client),
    ...migrationOnDemand(client),
    ...nameActions()(client),
    ...permissionOnDemand(client),
    ...planActions()(client),
    ...primaryNameActions()(client),
    ...recordActions()(client),
    ...registrationActions()(client),
    ...registryOnDemand(client),
    ...resolverActions()(client),
    ...roleOnDemand(client),
    ...subnameActions()(client),
    ...wrapperOnDemand(client),
    batch: (options) =>
      import("../../batch/index.js").then((module) => module.batch(client, options)),
  });
